#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXL = 60;

int t;
ll x, y, z;

int main() {
    cin >> t;
    while (t--) {
        cin >> x >> y >> z;
        ll a = 0, b = 0, c = 0;
        bool ans = true;
        for (int l = MAXL - 1; l >= 0; l--) {
            ll bit_x = x >> l & 1, bit_y = y >> l & 1, bit_z = z >> l & 1;
            bool found = false;
            for (ll bit_a : {0, 1}) {
                for (ll bit_b : {0, 1}) {
                    for (ll bit_c : {0, 1}) {
                        if ((bit_a & bit_b) == bit_x &&
                            (bit_b & bit_c) == bit_y &&
                            (bit_a & bit_c) == bit_z) {
                            found = true;
                            a |= bit_a << l;
                            b |= bit_b << l;
                            c |= bit_c << l;
                            break;
                        }
                    }
                    if (found) {
                        break;
                    }
                }
                if (found) {
                    break;
                }
            }
            if (!found) {
                ans = false;
                break;
            }
        }
        if (!ans) {
            cout << "NO\n";
        } else {
            assert((a & b) == x);
            assert((b & c) == y);
            assert((a & c) == z);
            cout << "YES\n";
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXN = 200'005;

int t;
int n;
int a[MAXN];
map<int, int> cnt;

int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    cin >> t;
    while (t--) {
        cnt.clear();

        cin >> n;
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }
        for (int i = 0; i < n; i++) {
            cnt[a[i]]++;
        }

        ll base = 0;
        vector<int> odd, even;
        for (auto [x, c] : cnt) {
            base += (ll)x * (c / 2);
            if (c % 2 == 1) {
                odd.push_back(x);
            } else if (c >= 2) {
                even.push_back(x);
            }
        }

        if (base == 0) {
            cout << 0 << '\n';
            continue;
        }

        ll ans = 0;
        for (int x : odd) {
            if (2 * base > x) {
                ans = max(ans, 2 * base + x);
            }
        }

        assert(is_sorted(odd.begin(), odd.end()));
        for (int i = 1; i < (int)odd.size(); i++) {
            if (odd[i - 1] + 2 * base > odd[i]) {
                ans = max(ans, odd[i - 1] + 2 * base + odd[i]);
            }
        }

        for (int x : even) {
            if (base - x > 0) {
                ans = max(ans, 2 * base);
            }
        }

        cout << ans << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll LINF = 1000000000000000005;
const int MAXN = 500005;

int t;
int n;
int a[MAXN];
ll dp[MAXN];

ll cost(int x, int y) { return abs(x - y); }

ll cost(int x, int y, int z) {
    if (x > y) {
        swap(x, y);
    }
    if (y > z) {
        swap(y, z);
    }
    if (x > y) {
        swap(x, y);
    }
    return z - x;
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    cin >> t;
    while (t--) {
        cin >> n;
        for (int i = 1; i <= n; i++) {
            cin >> a[i];
        }

        ll ans = LINF;
        for (int cyc = 0; cyc < 4; cyc++) {
            dp[0] = 0;
            dp[1] = LINF;
            for (int i = 2; i <= n; i++) {
                dp[i] = dp[i - 2] + cost(a[i - 1], a[i]);
                if (i >= 3) {
                    dp[i] =
                        min(dp[i], dp[i - 3] + cost(a[i - 2], a[i - 1], a[i]));
                }
            }
            ans = min(ans, dp[n]);

            // cyclic shift anti-clockwise
            for (int i = 2; i <= n; i++) {
                swap(a[i], a[i - 1]);
            }
        }

        cout << ans << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXN = 10000005;
const int INF = 1000000005;

bool is_prime[MAXN];

inline int calc_v(int p, int x) {
    int res = 0;
    ll pw_p = p;
    while (pw_p <= x) {
        res += x / pw_p;
        pw_p *= p;
    }
    return res;
}

int t;
int n, m;
vector<int> small_primes;

int main() {
#ifndef DEBUG
    ios::sync_with_stdio(0), cin.tie(0);
#endif
    for (int i = 2; i < MAXN; i++) {
        is_prime[i] = true;
    }
    for (int p = 2; (ll)p * p < MAXN; p++) {
        if (!is_prime[p]) {
            continue;
        }
        small_primes.push_back(p);
        for (int i = p * p; i < MAXN; i += p) {
            is_prime[i] = false;
        }
    }

    cin >> t;
    while (t--) {
        cin >> n >> m;

        // find largest prime q <= n. Requires at most 142 iterations (due to
        // prime gap)
        int q = n;
        while (!is_prime[q]) {
            q--;
        }

        // precompute the useful big primes
        vector<int> useful_p;
        for (int f = 1; (ll)f * f <= n; f++) {
            // p_bnd is the largest possible value such that floor(n / p_bnd) =
            // f n / p_bnd >= f p_bnd <= n / f
            int p_bnd = n / f;
            int p = p_bnd;
            while (!is_prime[p]) {
                p--;
            }
            useful_p.push_back(p);
        }

        ll ans = 0;
        // for all x < q, f_m(x, n) = 0. try all x >= q
        for (int x = q; x < n; x++) {
            int res = INF;

            for (int p : useful_p) {
                int vx = calc_v(p, x), vn = calc_v(p, n);
                if (vx != vn) {
                    res = min(res, vx);
                }
            }

            for (int p : small_primes) {
                if ((ll)p * p > m) {
                    break;
                }

                int base_vx = calc_v(p, x), base_vn = calc_v(p, n);
                for (ll exp = 1, pw_p = p; pw_p <= m; exp++, pw_p *= p) {
                    int vx = base_vx / exp, vn = base_vn / exp;
                    if (vx != vn) {
                        res = min(res, vx);
                    }
                }
            }

            ans += res;
        }

        cout << ans << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

namespace solution {

const int MAXL = 21;
const int MAXN = 1000005;

int n, q;
int a[MAXN];
vector<int> occ[MAXN];
ll pfx[MAXN], sfx[MAXN];
ll sm_pfx[MAXN], sm_sfx[MAXN];

inline bool is_first_occ(int i) { return occ[a[i]][0] == i; }
inline bool is_last_occ(int i) { return occ[a[i]].back() == i; }
// returns minimum j >= p such that a[j] == x, or n + 1 if does not exist
inline auto nxt_occ(int p, int x) {
    return lower_bound(occ[x].begin(), occ[x].end(), p);
}

int p[MAXL][MAXN];
vector<int> adj[MAXN];
inline void add_edge(int u, int v) {
    p[0][v] = u;
    adj[u].push_back(v);
}

int lvl[MAXN];
void dfs(int u) {
    for (int l = 1; l < MAXL; l++) {
        p[l][u] = p[l - 1][p[l - 1][u]];
    }
    if (u) {
        sm_pfx[u] += pfx[u];
        auto ptr = nxt_occ(u + 1, a[u]);
        sm_sfx[u] += ptr == occ[a[u]].end() ? 0 : sfx[*ptr];
    }
    for (int v : adj[u]) {
        lvl[v] = lvl[u] + 1;
        sm_pfx[v] = sm_pfx[u];
        sm_sfx[v] = sm_sfx[u];
        dfs(v);
    }
}

tuple<int, int, int> get_lca(int a, int b) {
    bool swp = false;
    if (lvl[a] < lvl[b]) {
        swap(a, b);
        swp = true;
    }
    for (int l = MAXL - 1; l >= 0; l--) {
        if (lvl[p[l][a]] >= lvl[b]) {
            a = p[l][a];
        }
    }
    if (a == b) {
        return {a, -1, -1};
    }
    if (swp) {
        swap(a, b);
    }
    for (int l = MAXL - 1; l >= 0; l--) {
        if (p[l][a] != p[l][b]) {
            a = p[l][a];
            b = p[l][b];
        }
    }
    return {p[0][a], a, b};
}

ll solve_same_layer(int l, int r) {
    assert(p[0][l] == p[0][r]);
    ll res =
        (pfx[r] -
         ((nxt_occ(r + 1, a[l]) - occ[a[l]].begin()) % 2 == 1 ? a[l] : 0)) -
        (pfx[l] -
         ((nxt_occ(l, a[l]) - occ[a[l]].begin() + 1) % 2 == 1 ? a[l] : 0));
    if ((nxt_occ(r + 1, a[l]) - nxt_occ(l, a[l])) % 2 == 1) {
        res += a[l];
    }
    return res;
}

void precompute() {
    for (int i = 0; i <= n; i++) {
        occ[i].clear();
        adj[i].clear();
        pfx[i] = sfx[i] = sm_pfx[i] = sm_sfx[i] = 0;
    }
    for (int i = 1; i <= n; i++) {
        occ[a[i]].push_back(i);
    }
    vector<int> stk;
    stk.push_back(0);
    for (int i = 1; i <= n; i++) {
        if (!is_first_occ(i)) {
            assert(!stk.empty() && a[stk.back()] == a[i]);
            stk.pop_back();
        }
        assert(!stk.empty());
        add_edge(stk.back(), i);
        if (!is_last_occ(i)) {
            stk.push_back(i);
        }
    }

    for (int u = n; u >= 0; u--) {
        {
            ll prv = 0;
            for (int i = 0; i < (int)adj[u].size(); i++) {
                int v = adj[u][i];
                auto ptr = nxt_occ(v, a[v]);
                pfx[v] =
                    prv + ((ptr - occ[a[v]].begin() + 1) % 2 == 1 ? a[v] : 0);
                if (!adj[v].empty()) {
                    prv += pfx[adj[v].back()];
                }
                if (is_last_occ(v)) {
                    prv += occ[a[v]].size() % 2 == 1 ? a[v] : 0;
                }
            }
        }
        {
            ll prv = 0;
            for (int i = (int)adj[u].size() - 1; i >= 0; i--) {
                int v = adj[u][i];
                auto ptr = nxt_occ(v, a[v]);
                if (!adj[v].empty()) {
                    prv += sfx[adj[v][0]];
                }
                sfx[v] = prv + ((occ[a[v]].end() - ptr) % 2 == 1 ? a[v] : 0);
                if (is_first_occ(v)) {
                    prv += occ[a[v]].size() % 2 == 1 ? a[v] : 0;
                }
            }
        }
    }

    dfs(0);
}

void init(int _n, int _q, vector<int> _a) {
    n = _n;
    q = _q;
    for (int i = 1; i <= n; i++) {
        a[i] = _a[i - 1];
    }
    precompute();
}

ll query(int l, int r) {
    if (l == r) {
        return a[l];
    }
    auto [lca, lc, rc] = get_lca(l, r);
    assert(lca != r);
    if (lca == l) {
        ll ans = sm_pfx[r] - sm_pfx[l] + a[l];
        return ans;
    } else if (lc == l) {
        ll ans = sm_pfx[r] - sm_pfx[rc];
        ans += solve_same_layer(l, rc);
        return ans;
    } else {
        ll ans = sfx[l] + sm_sfx[p[0][l]] - sm_sfx[lc] + sm_pfx[r] - sm_pfx[rc];
        ans += solve_same_layer(*nxt_occ(lc + 1, a[lc]), rc);
        return ans;
    }
}

} // namespace solution

int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int t;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        vector<int> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }

        solution::init(n, q, a);
        ll prv_ans = 0;
        while (q--) {
            int l, r;
            cin >> l >> r;
            auto decode = [&](int x) { return (x - 1 + prv_ans) % n + 1; };
            l = decode(l);
            r = decode(r);
            if (l > r) {
                swap(l, r);
            }
            ll ans = solution::query(l, r);
            cout << ans << ' ';
            prv_ans = ans;
        }
        cout << '\n';
    }
    return 0;
}
